drop function if exists public.business_set_promotion_active(uuid,boolean); drop function if exists public.business_set_location_active(uuid,boolean); drop function if exists public.business_set_qr_active(uuid,boolean); drop function if exists public.business_create_location(uuid,text,text,text,text,numeric,numeric); drop function if exists public.business_create_promotion(uuid,text,text,numeric,uuid,timestamptz,timestamptz); drop function if exists public.business_create_event(uuid,text,text,date,time,uuid); drop function if exists public.business_create_qr(uuid,uuid,text); create or replace function public.business_admin_guard(p_business_id uuid) returns boolean language sql security definer set search_path=public,pg_temp as $$ select exists(select 1 from business_members bm where bm.business_id=p_business_id and bm.user_id=auth.uid() and bm.role::text in ('owner','admin')) or exists(select 1 from profiles p where p.id=auth.uid() and coalesce(p.is_admin,false)); $$; create function public.business_create_location(p_business_id uuid,p_name text,p_address text default null,p_city text default null,p_state text default null,p_lat numeric default null,p_lng numeric default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not business_admin_guard(p_business_id) then raise exception 'admin access required'; end if; insert into locations(business_id,name,address,city,state,latitude,longitude,is_active) values(p_business_id,p_name,p_address,p_city,p_state,p_lat,p_lng,true) returning id into v_id; return v_id; end; $$; create function public.business_set_location_active(p_location_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare v_business uuid; begin select business_id into v_business from locations where id=p_location_id; if not business_admin_guard(v_business) then raise exception 'admin access required'; end if; update locations set is_active=p_active where id=p_location_id; return true; end; $$; create function public.business_create_promotion(p_business_id uuid,p_title text,p_description text default null,p_discount numeric default null,p_location_id uuid default null,p_starts_at timestamptz default now(),p_ends_at timestamptz default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not business_admin_guard(p_business_id) then raise exception 'admin access required'; end if; insert into promotions(business_id,title,description,discount,location_id,starts_at,ends_at,active,created_at) values(p_business_id,p_title,p_description,p_discount,p_location_id,p_starts_at,p_ends_at,true,now()) returning id into v_id; return v_id; end; $$; create function public.business_set_promotion_active(p_promotion_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare v_business uuid; begin select business_id into v_business from promotions where id=p_promotion_id; if not business_admin_guard(v_business) then raise exception 'admin access required'; end if; update promotions set active=p_active where id=p_promotion_id; return true; end; $$; create function public.business_create_event(p_business_id uuid,p_title text,p_description text default null,p_event_date date default null,p_event_time time default null,p_location_id uuid default null) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not business_admin_guard(p_business_id) then raise exception 'admin access required'; end if; insert into business_events(business_id,title,description,event_date,event_time,location_id,created_at) values(p_business_id,p_title,p_description,p_event_date,p_event_time,p_location_id,now()) returning id into v_id; return v_id; end; $$; create function public.business_create_qr(p_business_id uuid,p_location_id uuid,p_label text) returns uuid language plpgsql security definer set search_path=public,pg_temp as $$ declare v_id uuid; begin if not business_admin_guard(p_business_id) then raise exception 'admin access required'; end if; insert into qr_codes(location_id,label,active) select p_location_id,p_label,true where exists(select 1 from locations where id=p_location_id and business_id=p_business_id) returning id into v_id; if v_id is null then raise exception 'location does not belong to business'; end if; return v_id; end; $$; create function public.business_set_qr_active(p_qr_id uuid,p_active boolean) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare v_business uuid; begin select l.business_id into v_business from qr_codes q join locations l on l.id=q.location_id where q.id=p_qr_id; if not business_admin_guard(v_business) then raise exception 'admin access required'; end if; update qr_codes set active=p_active where id=p_qr_id; return true; end; $$;
